import type { Metadata } from "next";
import { absoluteUrl, siteConfig } from "@/lib/site";

interface PageMetadataInput {
  /** A string uses the site title template; `{ absolute }` bypasses it. */
  title: string | { absolute: string };
  description: string;
  /** Path of the page, e.g. "/about". */
  path: string;
  noIndex?: boolean;
}

/**
 * Builds consistent page metadata: title, description, canonical URL,
 * Open Graph and Twitter cards. The OG image is generated by
 * `app/opengraph-image.tsx` and inherited automatically.
 */
export function createMetadata({
  title,
  description,
  path,
  noIndex = false,
}: PageMetadataInput): Metadata {
  const url = absoluteUrl(path);
  const socialTitle =
    typeof title === "string"
      ? `${title} | ${siteConfig.name}`
      : title.absolute;

  return {
    title,
    description,
    alternates: { canonical: url },
    openGraph: {
      type: "website",
      siteName: siteConfig.name,
      locale: siteConfig.locale,
      title: socialTitle,
      description,
      url,
    },
    twitter: {
      card: "summary_large_image",
      title: socialTitle,
      description,
    },
    ...(noIndex ? { robots: { index: false, follow: false } } : {}),
  };
}
